python3 -c "
import json
target_eps = [0,3,4,7,10,12,13,15,16,17,18,20,21,26,28,29,31,34,36,39]
with open('/root/autodl-tmp/simgate-modular-routing/results/plan_c/find-non-living-thing/episodes.jsonl') as f:
    for line in f:
        ep = json.loads(line)
        idx = ep['episode_idx']
        if idx not in target_eps:
            continue
        ai = ep['always_internal']
        ad = ep['always_deterministic']
        # Find first scoring step for each
        ai_first = None
        for s in ai['steps']:
            if s['score_delta'] > 0:
                ai_first = s
                break
        ad_first = None
        for s in ad['steps']:
            if s['score_delta'] > 0:
                ad_first = s
                break
        print(f'EP {idx} | AI score={ai[\"final_score\"]} steps={ai[\"num_steps\"]} | AD score={ad[\"final_score\"]} steps={ad[\"num_steps\"]}')
        if ai_first:
            print(f'  AI first score: step {ai_first[\"step\"]} action=\"{ai_first[\"action\"]}\" delta={ai_first[\"score_delta\"]}')
        else:
            print(f'  AI first score: NONE (score=0)')
        if ad_first:
            print(f'  AD first score: step {ad_first[\"step\"]} action=\"{ad_first[\"action\"]}\" delta={ad_first[\"score_delta\"]}')
        else:
            print(f'  AD first score: NONE (score=0)')
        print()
"
